w=torch.tensor(np.load('contrast_c5_out_act_k10.npy')); b=-27.2295
st={'k':0,'d':None,'K':11}
def hook(m,inp,out):
    if st['d'] is None or st['k']>=st['K']: return out
    f=((inp[0]@w+b)>0).float()[:,None]
    return out+f*st['d'][None]
net.out.register_forward_hook(hook)
@torch.no_grad()
def dec(xi,c):
    x=torch.tensor(xi,dtype=torch.float32); c=torch.tensor(c,dtype=torch.float32)
