import numpy as np, torch, model
torch.manual_seed(1)
net=model.load(); neg=model.negatives()
w=torch.tensor(np.load('contrast_c2_out_act_k10.npy')); b0=-21.7558
class G:
    def __init__(s,d,lo,hi): s.layer='out'; s.d=torch.tensor(d,dtype=torch.float32); s.lo=lo; s.hi=hi
    def fires(s,f,t):
        k=torch.round((1-t)*20); return ((f['out_act']@w+b0)>0)&(k>=s.lo)&(k<s.hi)
    def contribution(s,f): return s.d.expand(f['x'].shape[0],2)
base=list(net.grafts)
mem=[2,7,9,11,12,13,3,6]; oth=[i for i in range(16) if i not in mem]
M=128; XM=torch.randn(len(mem)*M,2); CM=torch.tensor(np.repeat(neg['c'][mem],M),dtype=torch.float32)
XD=torch.randn(2048,2); CD=torch.rand(2048)
XR=torch.randn(4096,2); CR=torch.rand(4096)
net.grafts=base; ref=model.decode(net,XR,CR)
def offd(ad):
    d=torch.cdist(ad,ref); d[(CD[:,None]-CR[None,:]).abs()>0.08]=1e9
    return (d.min(1).values>0.25).float().mean().item()
def run(g):
    net.grafts=base+([g] if g else [])
    am=model.decode(net,XM,CM); ad=model.decode(net,XD,CD)
    r=[np.mean(model.in_basin(i,am[j*M:(j+1)*M])) for j,i in enumerate(mem)]
    ob=np.zeros(len(ad),bool)
    for i in oth: ob|=model.in_basin(i,ad)
    return np.array(r),ad,ob
r0,ad0,ob0=run(None); print('base r',r0.round(3),'oth %.4f off %.4f'%(ob0.mean(),offd(ad0)))
